  search(query: "user:ignazio-ingenito is:pr is:open", type: ISSUE, first: 100) {
    nodes {
      ... on PullRequest {
        number
        title
        body
        isDraft
        mergeable
        mergeStateStatus
        headRefName
        headRefOid
        reviewDecision
        author { login }
        labels(first: 20) { nodes { name } }
        repository {
          nameWithOwner
          mergeCommitAllowed
          squashMergeAllowed
          rebaseMergeAllowed
        }
        commits(last: 1) {
          nodes {
            commit {
              statusCheckRollup { state }
            }
          }
        }
      }
    }
  }
}"}

