const owner = 'ignazio-ingenito';
const allowedAuthors = new Set(['renovate[bot]', 'dependabot[bot]']);

function parseSemver(value) {
  const match = String(value || '').match(/v?(\d+)\.(\d+)\.(\d+)/);
  return match ? match.slice(1, 4).map(Number) : null;
}

function classify(pr) {
  const title = String(pr.title || '');
  const body = String(pr.body || '');
  const labels = (pr.labels?.nodes || []).map((label) => String(label.name || '').toLowerCase());

  if (labels.some((label) => label === 'security' || label === 'security-update')) return 'security';
  if (/\|\s*digest\s*\|/i.test(body) || /\bdigest\b/i.test(title)) return 'digest';
  const renovateType = body.match(/\|\s*(major|minor|patch)\s*\|/i);
  if (renovateType) return renovateType[1].toLowerCase();

  const dependabot = title.match(/\bfrom\s+([^\s`]+)\s+to\s+([^\s`]+)/i);
  if (dependabot) {
    const from = parseSemver(dependabot[1]);
    const to = parseSemver(dependabot[2]);
    if (from && to) {
      if (to[0] !== from[0]) return 'major';
      if (to[1] !== from[1]) return 'minor';
      if (to[2] !== from[2]) return 'patch';
    }
  }

  const versions = [...`${title}\n${body}`.matchAll(/v?(\d+)\.(\d+)\.(\d+)/g)].map((m) => m.slice(1, 4).map(Number));
  if (versions.length >= 2) {
    const from = versions[0];
    const to = versions[1];
    if (to[0] !== from[0]) return 'major';
    if (to[1] !== from[1]) return 'minor';
    if (to[2] !== from[2]) return 'patch';
  }
  return null;
}

const payload = $input.all()[0]?.json || {};
const prs = payload.data?.search?.nodes || [];

return prs.flatMap((pr) => {
  const author = pr.author?.login || '';
  const repo = pr.repository?.nameWithOwner || '';
  const head = pr.headRefName || '';
  const status = pr.commits?.nodes?.[0]?.commit?.statusCheckRollup?.state || null;

  if (!repo.startsWith(`${owner}/`)) return [];
  if (!allowedAuthors.has(author)) return [];
  if (pr.isDraft) return [];
  if (author === 'renovate[bot]' && !head.startsWith('renovate/')) return [];
  if (author === 'dependabot[bot]' && !head.startsWith('dependabot/')) return [];
  if (/configure renovate|renovate onboarding/i.test(`${pr.title || ''}\n${pr.body || ''}`)) return [];
  if (pr.mergeable !== 'MERGEABLE' || pr.mergeStateStatus !== 'CLEAN') return [];
  if (status !== 'SUCCESS') return [];
  if (pr.reviewDecision === 'CHANGES_REQUESTED' || pr.reviewDecision === 'REVIEW_REQUIRED') return [];

  const updateType = classify(pr);
  if (!updateType || updateType === 'major') return [];

  const mergeMethod = pr.repository?.squashMergeAllowed
    ? 'squash'
    : pr.repository?.mergeCommitAllowed
      ? 'merge'
      : pr.repository?.rebaseMergeAllowed
        ? 'rebase'
        : null;
  if (!mergeMethod) return [];

  const [repoOwner, repoName] = repo.split('/');
  return [{
    json: {
      repoOwner,
      repoName,
      repo,
      number: pr.number,
      title: pr.title,
      author,
      updateType,
      expectedHeadSha: pr.headRefOid,
      mergeMethod,
    },
  }];
});
